    43  /** @file Helper class to parse a XFile into a temporary structure */
    44  #ifndef AI_XFILEPARSER_H_INC
    45  #define AI_XFILEPARSER_H_INC
    46
    47  #include <string>
    48  #include <vector>
    49
    50  #include <assimp/types.h>
    51
    52  namespace Assimp {
    53      namespace XFile {
    54          struct Node;
    55          struct Mesh;
    56          struct Scene;
    57          struct Material;
    58          struct Animation;
    59          struct AnimBone;
    60      }
