    62  /**
    63    *     @brief  The XFileParser reads a XFile either in text or binary form and builds a temporary
    64    *             data structure out of it.
    65    */
    66  class XFileParser {
    67  public:
    68      /// Constructor. Creates a data structure out of the XFile given in the memory block.
    69      /// @param pBuffer Null-terminated memory buffer containing the XFile
    70      explicit XFileParser( const std::vector<char>& pBuffer);
    71
    72      /// Destructor. Destroys all imported data along with it
    73      ~XFileParser();
    74
    75      /// Returns the temporary representation of the imported data.
    76      XFile::Scene* GetImportedData() const { return mScene; }
    77
    78  protected:
    79      void ParseFile();
    80      void ParseDataObjectTemplate();
    81      void ParseDataObjectFrame( XFile::Node *pParent);
    82      void ParseDataObjectTransformationMatrix( aiMatrix4x4& pMatrix);
    83      void ParseDataObjectMesh( XFile::Mesh* pMesh);
    84      void ParseDataObjectSkinWeights( XFile::Mesh* pMesh);
    85      void ParseDataObjectSkinMeshHeader( XFile::Mesh* pMesh);
    86      void ParseDataObjectMeshNormals( XFile::Mesh* pMesh);
    87      void ParseDataObjectMeshTextureCoords( XFile::Mesh* pMesh);
    88      void ParseDataObjectMeshVertexColors( XFile::Mesh* pMesh);
    89      void ParseDataObjectMeshMaterialList( XFile::Mesh* pMesh);
    90      void ParseDataObjectMaterial( XFile::Material* pMaterial);
    91      void ParseDataObjectAnimTicksPerSecond();
    92      void ParseDataObjectAnimationSet();
    93      void ParseDataObjectAnimation( XFile::Animation* pAnim);
    94      void ParseDataObjectAnimationKey( XFile::AnimBone *pAnimBone);
    95      void ParseDataObjectTextureFilename( std::string& pName);
    96      void ParseUnknownDataObject();
    97
    98      //! places pointer to next begin of a token, and ignores comments
    99      void FindNextNoneWhiteSpace();
   100
   101      //! returns next valid token. Returns empty string if no token there
   102      std::string GetNextToken();
   103
   104      //! reads header of data object including the opening brace.
   105      //! returns false if error happened, and writes name of object
   106      //! if there is one
   107      void readHeadOfDataObject(std::string *poName = nullptr);
   108
   109      //! checks for closing curly brace, throws exception if not there
   110      void CheckForClosingBrace();
   111
   112      //! checks for one following semicolon, throws exception if not there
   113      void CheckForSemicolon();
   114
   115      //! checks for a separator char, either a ',' or a ';'
   116      void CheckForSeparator();
   117
   118      /// tests and possibly consumes a separator char, but does nothing if there was no separator
   119      void TestForSeparator();
   120
   121      //! reads a x file style string
   122      void GetNextTokenAsString( std::string& poString);
   123
   124      void ReadUntilEndOfLine();
   125
   126      unsigned short ReadBinWord();
   127      unsigned int ReadBinDWord();
   128      unsigned int ReadInt();
   129      ai_real ReadFloat();
   130      aiVector2D ReadVector2();
   131      aiVector3D ReadVector3();
   132      aiColor3D ReadRGB();
   133      aiColor4D ReadRGBA();
   134
   135      /** Throws an exception with a line number and the given text. */
   136      template<typename... T>
   137      AI_WONT_RETURN void ThrowException(T&&... args) AI_WONT_RETURN_SUFFIX;
